import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, noise, texture } from 'three/tsl';

export default function createNode(config, ctx) {
  const Three = ctx.THREE;
  const Group = Three.Group;
  const Mesh = Three.Mesh;
  const PlaneGeometry = Three.PlaneGeometry;
  const Color = Three.Color;

  const group = new Group();

  const colors = config.intent?.visualSpec?.colors ?? {};
  const surface = new Color(colors.surface ?? '#0b0b10');
  const ink = new Color(colors.ink ?? '#16161d');
  const accent = new Color(colors.accent ?? '#ff2a38');
  const paper = new Color(colors.paper ?? '#e8ecf2');

  // Engineered gradient surface + subtle grain backdrop for the decor plane.
  const planeGeo = new PlaneGeometry(2.6, 1.6);
  const planeMat = new MeshBasicNodeMaterial({ transparent: true });

  const vUv = uv();
  const gradT = smoothstep(0.0, 1.0, vUv.y);
  const gradColor = mix(
    vec3(surface.r, surface.g, surface.b),
    vec3(ink.r, ink.g, ink.b),
    gradT
  );
  const grain = noise(vUv.mul(520.0)).mul(0.018);
  const baseColor = gradColor.add(vec3(grain, grain, grain));

  // Subtle accent edge glow along the lower band to imply CTA energy without interaction.
  const edgeBand = smoothstep(0.82, 1.0, vUv.y);
  const accentTint = vec3(accent.r, accent.g, accent.b).mul(edgeBand.mul(0.18));
  planeMat.colorNode = baseColor.add(accentTint);

  const plane = new Mesh(planeGeo, planeMat);
  group.add(plane);

  // Thin paper-tone hairline frame around the plane (machined atelier edge).
  const frameGeo = new PlaneGeometry(2.62, 1.62);
  const frameMat = new MeshBasicNodeMaterial({ transparent: true, opacity: 0.5 });
  frameMat.colorNode = vec3(paper.r * 0.5, paper.g * 0.5, paper.b * 0.5);
  const frame = new Mesh(frameGeo, frameMat);
  frame.position.z = -0.001;
  group.add(frame);

  let loadedTex = null;
  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    loadedTex = tex;
    tex.colorSpace = Three.SRGBColorSpace;
    const texColor = texture(tex);
    // Composite the orb asset over the engineered gradient: keep texture character
    // but tint toward the spec palette so it sits on the dark stage.
    const composed = mix(texColor.rgb, baseColor.add(accentTint), 0.14);
    planeMat.colorNode = composed;
    planeMat.alphaNode = texColor.a;
    planeMat.needsUpdate = true;
  });

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    planeGeo.dispose();
    planeMat.dispose();
    frameGeo.dispose();
    frameMat.dispose();
    if (loadedTex) loadedTex.dispose();
  };

  return group;
}
